fn wait(mut f:impl FnMut()->bool){let until=Instant::now()+Duration::from_secs(90);while !f(){assert!(Instant::now()<until,"R484 bounded wait timeout");thread::sleep(Duration::from_millis(5));}}
fn choose(rt:&mut Runtime,mode:u8,id:u32){rt.handle(Action::Filter(Filter::Mode{mode,alternate:false})).unwrap();rt.handle(Action::Select(mode,id)).unwrap();}
